-- 20261105 rof2b port: roost - Blackfeather Roost (15 quests, 3 parent jewellery sets).
-- Source: github.com/nightstalker6669/EQEmu branch rof2-achievements,
--   extensions/rof2/achievements/content/roost (GPL-3.0), ported 2026-11-05.
-- Forward SQL files concatenated verbatim in install order; fail-closed
-- guards and session variables preserved. Reviewed-flag acceptance block
-- added here (upstream reconstruction defaults documented in the package's
-- provenance/ directory; see docs/rof2-zone-quests-attribution.md).
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
SET @roost_catalogue_reviewed=1;
SET @roost_acquisition_reviewed=1;
SET @roost_tasks_reviewed=1;
SET @roost_parent_rewards_reviewed=1;
SET @roost_nests_reviewed=1;
SET @roost_activation_reviewed=1;
-- (reviewed flags accepted: @roost_catalogue_reviewed, @roost_acquisition_reviewed, @roost_tasks_reviewed, @roost_parent_rewards_reviewed, @roost_nests_reviewed, @roost_activation_reviewed)

-- ---- roost/sql/01_catalogue.sql ----
-- Roost production content; guarded disabled base import.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS _roost_catalogue_guard;
CREATE TEMPORARY TABLE _roost_catalogue_guard(label VARCHAR(80)PRIMARY KEY,ok TINYINT NOT NULL,CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
ON DUPLICATE KEY UPDATE `id`=VALUES(`id`);
ON DUPLICATE KEY UPDATE `id`=VALUES(`id`);
ON DUPLICATE KEY UPDATE `achievement_id`=VALUES(`achievement_id`);
ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`);
ON DUPLICATE KEY UPDATE `achievement_id`=VALUES(`achievement_id`);
COMMIT;

